CREATE TABLE IF NOT EXISTS invitations (id INTEGER PRIMARY KEY AUTOINCREMENT,app_id TEXT NOT NULL DEFAULT 'principal-ed',subject_component TEXT NOT NULL,subject_type TEXT NOT NULL,subject_id TEXT NOT NULL,audience_id INTEGER,party_type TEXT NOT NULL CHECK(party_type IN ('user','staff','student','guardian','team','external')),party_id TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'invitee',status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','declined','tentative','cancelled','withdrawn')),response_notes TEXT,responded_at TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')),UNIQUE(app_id,subject_component,subject_type,subject_id,party_type,party_id,role));
CREATE INDEX IF NOT EXISTS idx_invitations_subject ON invitations(app_id,subject_component,subject_type,subject_id,status);CREATE INDEX IF NOT EXISTS idx_invitations_party ON invitations(app_id,party_type,party_id,status);
